def count_pairs_with_sum(nums, target):
    from collections import Counter
    cnt = Counter(nums)
    total = 0
    for v, c in cnt.items():
        w = target - v
        if w == v:
            total += c * (c - 1) // 2
        elif w in cnt and v < w:
            total += c * cnt[w]
    return total

